  ('pdf-to-text', 'PDF Text Extractor', 'PDF Tools', 'Extract raw text content from PDF files directly in your browser without uploading to external servers.', 'FileText', '/tools/pdf-to-text', 'file', true, true, true, 0, '{"title": "Free PDF Text Extractor Tool — BRANIFY", "keywords": ["pdf to text", "extract pdf text", "pdf reader", "pdf converter"], "description": "Extract text from any PDF document online instantly in your browser."}'::jsonb, false),
